import React, { useState } from 'react';
import styled from 'styled-components';

const HeaderBar = styled.header`
  width: 100%;
  padding: 2.5rem 4rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: ${({ theme }) => theme.bg};
  color: ${({ theme }) => theme.text};
  border-bottom: 1px solid ${({ theme }) => theme.border};
  position: sticky;
  top: 0;
  z-index: 100;
`;

const Name = styled.div`
  font-size: 2rem;
  font-weight: 900;
  letter-spacing: -1px;
`;

const Nav = styled.nav`
  display: flex;
  align-items: center;
  gap: 2.5rem;
`;

const NavLink = styled.a`
  font-size: 1.1rem;
  font-weight: 600;
  color: ${({ theme }) => theme.text};
  opacity: 0.85;
  text-decoration: none;
  transition: opacity 0.18s;
  &:hover, &:focus {
    opacity: 1;
  }
`;

const ContactBtn = styled.a`
  padding: 0.6rem 1.5rem;
  border-radius: 100px;
  border: 2px solid ${({ theme }) => theme.text};
  background: transparent;
  color: ${({ theme }) => theme.text};
  font-weight: 700;
  font-size: 1rem;
  margin-left: 2rem;
  transition: background 0.2s, color 0.2s;
  cursor: pointer;
  &:hover, &:focus {
    background: ${({ theme }) => theme.text};
    color: ${({ theme }) => theme.bg};
  }
`;

const Switch = styled.button`
  margin-left: 2rem;
  background: ${({ theme }) => theme.bg};
  color: ${({ theme }) => theme.text};
  border: 2px solid ${({ theme }) => theme.text};
  border-radius: 100px;
  padding: 0.5rem 1.2rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
  &:hover, &:focus {
    background: ${({ theme }) => theme.text};
    color: ${({ theme }) => theme.bg};
  }
`;

const themes = {
  dark: {
    bg: '#000',
    text: '#fff',
    border: '#222',
  },
  light: {
    bg: '#fff',
    text: '#000',
    border: '#eee',
  },
};

const Header = () => {
  const [mode, setMode] = useState('dark');
  const theme = themes[mode];

  return (
    <HeaderBar theme={theme}>
      <Name>Valdrin Shala</Name>
      <Nav>
        <NavLink theme={theme} href="#home">Home</NavLink>
        <NavLink theme={theme} href="#projects">Work</NavLink>
        <NavLink theme={theme} href="#about">About</NavLink>
        <Switch theme={theme} onClick={() => setMode(mode === 'dark' ? 'light' : 'dark')}>
          {mode === 'dark' ? 'Light Mode' : 'Dark Mode'}
        </Switch>
        <ContactBtn theme={theme} href="#contact">Contact Me</ContactBtn>
      </Nav>
    </HeaderBar>
  );
};

export default Header;
